import java.io.*;
import java.math.BigInteger;
import java.util.*;

/*
Прокрастинирую
*/

public class Main {

    static FastReader in;
    static PrintWriter out;
    static Random rand = new Random();
    static final int INF = (int) (1e9 + 10), MOD = (int) (998244353), LOGN = 20;
    static final long IINF = (long) (2e18 + 10);

    static long pow(long a, long b) {
        long res = 1;
        while (b != 0) {
            if ((b & 1) != 0) {
                res = (res * a) % MOD;
            }
            a = (a * a) % MOD;
            b >>= 1;
        }
        return res;
    }

    static long even, odd;
    static HashMap<Long, Long> dp0;
    static HashMap<Long, Long> dp1;
    static long go(long n, int x) {
        if (x == 0) {
            if (dp0.containsKey(n)) {
                return dp0.get(n);
            }
            if (n == 1) {
                long res = even;
                dp0.put(n, res);
                return res;
            } else if (n == 2) {
                long res = (even * even + odd * odd) % MOD;
                dp0.put(n, res);
                return res;
            }
            long a1 = go(n / 2, 0);
            long a2 = go(n - n / 2, 0);
            long b1 = go(n / 2, 1);
            long b2 = go(n - n / 2, 1);
            long res = (a1 * a2 + b1 * b2) % MOD;
            dp0.put(n, res);
            return res;
        } else {
            if (dp1.containsKey(n)) {
                return dp1.get(n);
            }
            if (n == 1) {
                long res = odd;
                dp1.put(n, res);
                return res;
            } else if (n == 2) {
                long res = (even * odd + odd * even) % MOD;
                dp1.put(n, res);
                return res;
            }
            long a1 = go(n / 2, 0);
            long a2 = go(n - n / 2, 1);
            long b1 = go(n / 2, 1);
            long b2 = go(n - n / 2, 0);
            long res = (a1 * a2 + b1 * b2) % MOD;
            dp1.put(n, res);
            return res;
        }
    }

    static void solve() {
        long n = in.nextInt();
        long m = in.nextInt();
        long l = in.nextInt();
        long r = in.nextInt();
        long sz = n * m;

        if (sz % 2 == 0) {
            even = (r - l + 1) / 2;
            if ((r - l) % 2 == 0 && l % 2 == 0) even++;
            odd = r - l + 1 - even;

            dp0 = new HashMap<>();
            dp1 = new HashMap<>();
            out.println(go(sz, 0));
        } else {
            long ans = pow(r - l + 1, sz);
            out.println(ans);
        }
    }

    public static void main(String[] args) throws FileNotFoundException {
        in = new FastReader(System.in);
//        in = new FastReader(new FileInputStream("sometext.txt"));
        out = new PrintWriter(System.out);
//        out = new PrintWriter(new FileOutputStream("sometext.txt"));

        int tests = 1;
//        tests = in.nextInt();

        while (tests-- > 0) {
            solve();
        }

//        out.flush();
        out.close();
    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        Integer nextInt() {
            return Integer.parseInt(next());
        }

        Long nextLong() {
            return Long.parseLong(next());
        }

        Double nextDouble() {
            return Double.parseDouble(next());
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(nextLine());
            }
            return st.nextToken();
        }

        String nextLine() {
            String s = "";
            try {
                s = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return s;
        }
    }
}
